231	std::vector<torch::Tensor> OperationWrapper::Forward(std::vector<torch::Tensor> &inTensors)
232	{
233	    Mki::Timer runTimer;
234	    if (!operation_) {
235	        throw std::runtime_error("call Forward fail, operation is nullptr");
236	    }
237	    std::vector<torch::Tensor> outTensors;
238	    Setup(inTensors, outTensors);
239	    Execute();
240	    ProfStats::GetProfStats().SetRunTime(GetName(), runTimer.ElapsedMicroSecond());
241	    return outTensors;
242	}
243	
244	atb::SVector<atb::TensorDesc> OperationWrapper::InferShape()
245	{
246	    if (!operation_) {
247	        throw std::runtime_error("call InferShape fail, operation is nullptr");
248	    }
249	    atb::SVector<atb::TensorDesc> inTensorDescs;
250	    inTensorDescs.resize(variantPack_.inTensors.size());
251	    for (size_t i = 0; i < inTensorDescs.size(); ++i) {
252	        inTensorDescs.at(i) = variantPack_.inTensors.at(i).desc;
253	    }
254	    atb::SVector<atb::TensorDesc> outTensorDescs;
255	    Status st = operation_->InferShape(inTensorDescs, outTensorDescs);
256	    if (st != NO_ERROR) {
257	        throw std::runtime_error("call operation_->InferShape fail");
258	    }
259	    return outTensorDescs;
260	}
261	
262	void OperationWrapper::Setup(std::vector<torch::Tensor> &inTensors, std::vector<torch::Tensor> &outTensors)
263	{
264	    if (!operation_) {
265	        throw std::runtime_error("call Setup fail, operation is nullptr");
266	    }
267	    BuildInTensorVariantPack(inTensors);
268	    atb::SVector<atb::TensorDesc> outTensorDescs = InferShape();
269	    outTensors.resize(outTensorDescs.size());
270	    for (size_t i = 0; i < outTensorDescs.size(); ++i) {
271	        outTensors.at(i) = Utils::CreateTorchTensorFromTensorDesc(outTensorDescs.at(i));
272	    }
273	    variantPack_.outTensors.resize(outTensors.size());
274	    for (size_t i = 0; i < outTensors.size(); ++i) {
275	        variantPack_.outTensors.at(i) = Utils::ConvertToAtbTensor(outTensors.at(i));
276	    }
277	    atb::Context *context = Utils::GetAtbContext();
278	    atb::Status st = operation_->Setup(variantPack_, workspaceSize_, context);
279	    if (st != NO_ERROR) {
280	        throw std::runtime_error("call operation_->Setup fail");
281	    }
282	}
283	
284	void OperationWrapper::Execute()
285	{
286	    if (!operation_) {
287	        throw std::runtime_error("call Execute fail, operation is nullptr");
288	    }
289	    uint8_t *workspace = nullptr;
290	    ATB_LOG(INFO) << "workspaceSize_: " << workspaceSize_;
291	    if (workspaceSize_ > 0) {
292	        workspace = (uint8_t *)MemoryManager::GetMemoryManager().GetWorkspaceBuffer(workspaceSize_);
293	    }
294	    atb::Context *context = Utils::GetAtbContext();
295	    if (Utils::IsTaskQueueEnable()) {
296	        ATB_LOG(DEBUG) << "IsTaskQueueEnable";
297	        at_npu::native::OpCommand cmd;
298	        cmd.Name(operation_->GetName());
299	        cmd.SetCustomHandler([=]() { return operation_->Execute(variantPack_, workspace, workspaceSize_, context); });
300	        cmd.Run();
301	        return;
302	    }
303	    Status st = operation_->Execute(variantPack_, workspace, workspaceSize_, context);
304	    if (st != NO_ERROR) {
305	        throw std::runtime_error("call operation_->Execute fail");
306	    }
307	    int ret = aclrtSynchronizeStream(context->GetExecuteStream());
308	    if (ret != 0) {
309	        throw std::runtime_error("call aclrtSynchronizeStream fail");
310	    }
311	}
312	
313	void OperationWrapper::BuildInTensorVariantPack(std::vector<torch::Tensor> &inTensors)
314	{
315	    variantPack_.inTensors.resize(inTensors.size());
316	    for (size_t i = 0; i < inTensors.size(); ++i) {
317	        variantPack_.inTensors.at(i) = Utils::ConvertToAtbTensor(inTensors.at(i));
318	    }
319	}
